#requires -Version 5.1
#requires -RunAsAdministrator
[CmdletBinding()]
param()
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$root = Join-Path $env:ProgramData 'HostBase'
New-Item -Path $root -ItemType Directory -Force | Out-Null
# Logs and reports must not be writable by a standard host user.
& icacls.exe $root /inheritance:r /grant:r '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F' | Out-Null
if ($LASTEXITCODE -ne 0) { throw 'Could not protect HostBase log directory.' }
Start-Transcript -Path (Join-Path $root 'Apply-Base.log') -Append | Out-Null
$warnings = [System.Collections.Generic.List[string]]::new()
$changes = [System.Collections.Generic.List[string]]::new()
$restartNeeded = $false
function Set-Dword([string]$Path, [string]$Name, [int]$Value) {
    New-Item -Path $Path -Force | Out-Null
    New-ItemProperty -Path $Path -Name $Name -Value $Value -PropertyType DWord -Force | Out-Null
}
function Invoke-CheckedNative([string]$File, [string[]]$Arguments) {
    & $File @Arguments
    if ($LASTEXITCODE -ne 0) { throw "$File failed with exit code $LASTEXITCODE." }
}
try {
    if (-not [Environment]::Is64BitProcess -or $env:PROCESSOR_ARCHITECTURE -ne 'AMD64') {
        throw 'Run using 64-bit Windows PowerShell on the x64 target.'
    }
    $edition = (Get-WindowsEdition -Online).Edition
    $profile = Get-Content -LiteralPath (Join-Path $PSScriptRoot 'HostProfile.json') -Raw | ConvertFrom-Json
    if ($edition -ne $profile.targetEdition) {
        throw "Expected Windows 11 Pro for Workstations (ProfessionalWorkstation); found $edition. Use the matching stock ISO image."
    }
    $os = Get-CimInstance Win32_OperatingSystem
    if ([int]$os.BuildNumber -lt 22000) { throw 'This profile requires Windows 11.' }
    if (@($profile.removeAppx | Where-Object { $_ -in $profile.protectedAppx }).Count -gt 0) {
        throw 'The Appx removal list overlaps protected host dependencies.'
    }
    if (@($profile.disabledServices | Where-Object { $_ -in $profile.requiredServices }).Count -gt 0) {
        throw 'The disabled-service list overlaps a required host dependency.'
    }

    # Preserve stock protected/trigger-start service settings. Never force all services to Automatic.
    foreach ($name in $profile.requiredServices) {
        $service = Get-Service -Name $name -ErrorAction SilentlyContinue
        if (-not $service) { throw "Required stock service missing: $name" }
        if ($service.StartType -eq 'Disabled') { throw "Required service disabled: $name. Repair the stock image before proceeding." }
    }
    Set-Service -Name DiagTrack -StartupType Automatic
    # Start after OOBE if not yet runnable during specialize; do not suppress telemetry endpoints.
    try { Start-Service DiagTrack } catch { $warnings.Add("DiagTrack startup deferred: $($_.Exception.Message)") }

    # The WHP API, not the full Hyper-V management role, is the required VMware interface.
    $whp = Get-WindowsOptionalFeature -Online -FeatureName HypervisorPlatform
    if ($whp.State -ne 'Enabled') {
        $result = Enable-WindowsOptionalFeature -Online -FeatureName HypervisorPlatform -All -NoRestart
        $restartNeeded = $restartNeeded -or $result.RestartNeeded
    }
    Invoke-CheckedNative bcdedit.exe @('/set', 'hypervisorlaunchtype', 'auto')
    $dg = 'HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard'
    Set-Dword $dg 'EnableVirtualizationBasedSecurity' 1
    # Require Secure Boot + DMA protection; unsupported firmware must fail host validation.
    Set-Dword $dg 'RequirePlatformSecurityFeatures' 3
    Set-Dword "$dg\Scenarios\HypervisorEnforcedCodeIntegrity" 'Enabled' 1
    Set-Dword "$dg\Scenarios\HypervisorEnforcedCodeIntegrity" 'Locked' 0
    Set-Dword 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' 'LsaCfgFlags' 2
    Set-Dword 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' 'RunAsPPL' 2
    Set-Dword 'HKLM:\SYSTEM\CurrentControlSet\Control\CI\Config' 'VulnerableDriverBlocklistEnable' 1
    $restartNeeded = $true
    $changes.Add('WHP, VBS/HVCI, Credential Guard and LSA protection configured; runtime validation after reboot is mandatory.')

    # Keep encryption automatic when eligible. Never enroll encryption keys in this file.
    Remove-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\BitLocker' -Name PreventDeviceEncryption -ErrorAction SilentlyContinue
    Set-Dword 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection' 'AllowTelemetry' 1
    Set-Dword 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\System' 'EnableSmartScreen' 1
    New-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\System' -Name ShellSmartScreenLevel -Value 'Block' -PropertyType String -Force | Out-Null
    Set-Dword 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsAI' 'DisableAIDataAnalysis' 1
    Set-Dword 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsCopilot' 'TurnOffWindowsCopilot' 1
    Set-Dword 'HKLM:\SOFTWARE\Policies\Microsoft\Dsh' 'AllowNewsAndInterests' 0
    Set-Dword 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent' 'DisableWindowsConsumerFeatures' 1
    Set-Dword 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent' 'DisableCloudOptimizedContent' 1
    Set-Dword 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\OneDrive' 'DisableFileSyncNGSC' 1
    Set-Dword 'HKLM:\SOFTWARE\Policies\Microsoft\Edge' 'HideFirstRunExperience' 1
    Set-Dword 'HKLM:\SOFTWARE\Policies\Microsoft\Edge' 'StartupBoostEnabled' 0
    Set-Dword 'HKLM:\SOFTWARE\Policies\Microsoft\Edge' 'BackgroundModeEnabled' 0
    Set-Dword 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR' 'AllowGameDVR' 0
    Set-Dword 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power' 'HiberbootEnabled' 0
    Set-Dword 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem' 'LongPathsEnabled' 1
    Set-Dword 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'EnableLUA' 1
    Set-Dword 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'PromptOnSecureDesktop' 1
    Set-Dword 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'ConsentPromptBehaviorAdmin' 2
    Set-Dword 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'ConsentPromptBehaviorUser' 1
    Set-Dword 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'InactivityTimeoutSecs' 600
    Set-Dword 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'DisableAutomaticRestartSignOn' 1
    Set-Dword 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server' 'fDenyTSConnections' 1
    Set-Dword 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient' 'EnableMulticast' 0
    Invoke-CheckedNative net.exe @('accounts', '/minpwlen:14', '/maxpwage:unlimited', '/lockoutthreshold:10', '/lockoutduration:15', '/lockoutwindow:15')
    Invoke-CheckedNative net.exe @('user', 'Guest', '/active:no')
    # Applies to this new stock installation. Do not rerun after third-party firewall deployment.
    Set-NetFirewallProfile -Profile Domain,Private,Public -Enabled True -DefaultInboundAction Block -DefaultOutboundAction Allow
    # Leave IPv4/IPv6, BFE, mpssvc, SharedAccess, cryptography and servicing intact.
    Set-SmbServerConfiguration -EnableSMB1Protocol $false -EnableSMB2Protocol $true -RequireSecuritySignature $true -Force
    Set-SmbClientConfiguration -RequireSecuritySignature $true -EnableInsecureGuestLogons $false -Force

    $features = @(Get-WindowsOptionalFeature -Online)
    foreach ($name in $profile.disableFeatures) {
        $feature = $features | Where-Object FeatureName -EQ $name
        if ($feature -and $feature.State -eq 'Enabled') {
            try {
                # No -Remove: preserve feature payloads and Windows component servicing.
                $result = Disable-WindowsOptionalFeature -Online -FeatureName $name -NoRestart
                $restartNeeded = $restartNeeded -or $result.RestartNeeded
                $changes.Add("Disabled optional feature: $name")
            } catch { $warnings.Add("Feature $name not disabled: $($_.Exception.Message)") }
        }
    }
    foreach ($name in $profile.disabledServices) {
        $service = Get-Service -Name $name -ErrorAction SilentlyContinue
        if ($service) {
            try {
                if ($service.Status -ne 'Stopped') { Stop-Service -Name $name -Force }
                Set-Service -Name $name -StartupType Disabled
                $changes.Add("Disabled optional service: $name")
            } catch { $warnings.Add("Service $name not disabled: $($_.Exception.Message)") }
        }
    }
    & (Join-Path $PSScriptRoot 'Trim-Apps.ps1')
    & (Join-Path $PSScriptRoot 'Set-DefaultProfile.ps1')
    [ordered]@{
        Version = $profile.profileVersion; Success = $true; RestartRequired = $restartNeeded
        WarningCount = $warnings.Count; Warnings = @($warnings.ToArray()); Changes = @($changes.ToArray())
        Note = 'Configuration applied, not proof of runtime security. Run Test-Host.ps1 after reboot.'
    } | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $root 'Apply-Base.json') -Encoding UTF8
    foreach ($warning in $warnings) { Write-Warning $warning }
} catch {
    [ordered]@{ Success = $false; Error = $_.Exception.Message } | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $root 'Apply-Base.json') -Encoding UTF8
    throw
} finally { Stop-Transcript | Out-Null }

#requires -Version 5.1
#requires -RunAsAdministrator
[CmdletBinding()]
param([string]$SenseSource)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
if (-not [Environment]::Is64BitProcess) { throw 'Use 64-bit Windows PowerShell.' }
$root = Join-Path $env:ProgramData 'HostBase'
if (-not (Test-Path -LiteralPath (Join-Path $root 'Apply-Base.json'))) { throw 'Base installation report missing.' }
$base = Get-Content (Join-Path $root 'Apply-Base.json') -Raw | ConvertFrom-Json
if (-not $base.Success) { throw 'Resolve the failed Apply-Base report first.' }
Start-Transcript -Path (Join-Path $root 'Initialize-Host.log') -Append | Out-Null
try {
    # Run before Bitdefender/Mullvad; do not override a third-party antivirus or firewall.
    $otherAv = @(Get-CimInstance -Namespace root/SecurityCenter2 -ClassName AntivirusProduct |
        Where-Object { $_.displayName -notmatch '(?i)Microsoft Defender|Windows Defender' })
    if ($otherAv.Count) { throw 'Run Initialize-Host before third-party antivirus installation; do not overwrite the stack.' }
    Set-Service DiagTrack -StartupType Automatic
    Start-Service DiagTrack
    Start-Service WlanSvc
    $physical = @(Get-NetAdapter -Physical)
    foreach ($adapter in $physical) {
        foreach ($connection in @(Get-NetConnectionProfile -InterfaceIndex $adapter.ifIndex -ErrorAction SilentlyContinue)) {
            if ($connection.NetworkCategory -ne 'DomainAuthenticated') {
                Set-NetConnectionProfile -InterfaceIndex $adapter.ifIndex -NetworkCategory Public
            }
        }
        # No host LAN file sharing; VMnet adapters are deliberately excluded.
        $sharing = Get-NetAdapterBinding -Name $adapter.Name -ComponentID ms_server -ErrorAction SilentlyContinue
        if ($sharing -and $sharing.Enabled) { Disable-NetAdapterBinding -Name $adapter.Name -ComponentID ms_server | Out-Null }
    }
    if (-not (Get-NetFirewallRule -Name HostBase-BlockOutboundSMB-TCP -ErrorAction SilentlyContinue)) {
        New-NetFirewallRule -Name HostBase-BlockOutboundSMB-TCP -DisplayName 'HostBase: block outbound SMB on Public networks' -Direction Outbound -Action Block -Protocol TCP -RemotePort 139,445 -Profile Public | Out-Null
    }
    if (-not (Get-NetFirewallRule -Name HostBase-BlockNetBIOS-UDP -ErrorAction SilentlyContinue)) {
        New-NetFirewallRule -Name HostBase-BlockNetBIOS-UDP -DisplayName 'HostBase: block outbound NetBIOS on Public networks' -Direction Outbound -Action Block -Protocol UDP -RemotePort 137,138 -Profile Public | Out-Null
    }
    # Defender remains the active AV until a registered third-party AV is installed.
    Set-MpPreference -PUAProtection Enabled -DisableRealtimeMonitoring $false -DisableBehaviorMonitoring $false `
        -DisableIOAVProtection $false -DisableScriptScanning $false -DisableBlockAtFirstSeen $false `
        -MAPSReporting Advanced -SubmitSamplesConsent SendSafeSamples -EnableNetworkProtection Enabled
    # No AV exclusions, ASR enforcement, TLS-inspection exceptions, or passive-mode registry hacks.
    foreach ($guid in @('{0CCE922B-69AE-11D9-BED3-505054503030}',
        '{0CCE9215-69AE-11D9-BED3-505054503030}', '{0CCE921B-69AE-11D9-BED3-505054503030}',
        '{0CCE9235-69AE-11D9-BED3-505054503030}', '{0CCE923F-69AE-11D9-BED3-505054503030}')) {
        & auditpol.exe /set "/subcategory:$guid" /success:enable /failure:enable
        if ($LASTEXITCODE -ne 0) { throw 'Failed to enable an audit subcategory.' }
    }
    foreach ($spec in @(@('Security',134217728), @('System',67108864), @('Application',67108864))) {
        & wevtutil.exe sl $spec[0] "/ms:$($spec[1])"
        if ($LASTEXITCODE -ne 0) { throw "Failed to size event channel $($spec[0])." }
    }
    # Sense may be built in. Never assume that a universal FoD name or release exists.
    if (-not (Get-Service Sense -ErrorAction SilentlyContinue)) {
        $sense = @(Get-WindowsCapability -Online | Where-Object Name -Like 'Microsoft.Windows.Sense.Client*')
        if ($sense.Count -eq 1) {
            if ($SenseSource) {
                Add-WindowsCapability -Online -Name $sense[0].Name -Source $SenseSource -LimitAccess | Out-Null
            } else {
                Add-WindowsCapability -Online -Name $sense[0].Name | Out-Null
            }
        } else {
            throw 'Sense is missing and its capability is unavailable. Obtain the matching official Windows FoD/EDR package; do not onboard yet.'
        }
    }
    & (Join-Path $PSScriptRoot 'Trim-Apps.ps1')
    Write-Host 'Base initialization completed. Reboot, patch Windows, and run Test-Host.ps1. Third-party products are not installed or onboarded.'
} finally { Stop-Transcript | Out-Null }

#requires -Version 5.1
#requires -RunAsAdministrator
[CmdletBinding()]
param([switch]$AddAcademicAndUsers)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
if (-not [Environment]::Is64BitProcess) { throw 'Use 64-bit Windows PowerShell.' }
# No transcript, stored password, auto-logon, account overwrite, or automatic demotion.
$accounts = @([pscustomobject]@{ Name = 'HOST-ADMIN'; Admin = $true },
    [pscustomobject]@{ Name = 'WORK'; Admin = $false })
if ($AddAcademicAndUsers) {
    $accounts += @([pscustomobject]@{ Name = 'ACADEMIC'; Admin = $false },
        [pscustomobject]@{ Name = 'USERS'; Admin = $false })
}
foreach ($account in $accounts) {
    if (Get-LocalUser -Name $account.Name -ErrorAction SilentlyContinue) {
        throw "Account $($account.Name) already exists. Review it manually; this script will not replace accounts or passwords."
    }
}
$adminGroup = Get-LocalGroup -SID 'S-1-5-32-544'
$usersGroup = Get-LocalGroup -SID 'S-1-5-32-545'
foreach ($account in $accounts) {
    $password = Read-Host "Enter a unique password of at least 14 characters for $($account.Name)" -AsSecureString
    try {
        if ($password.Length -lt 14) { throw 'Password too short. No account was created for this prompt.' }
        $user = New-LocalUser -Name $account.Name -Password $password -PasswordNeverExpires `
            -Description 'Windows host account; created interactively without unattended credentials.'
        Add-LocalGroupMember -Group $usersGroup -Member $user
        if ($account.Admin) { Add-LocalGroupMember -Group $adminGroup -Member $user }
    } finally { $password.Dispose() }
}
Write-Host 'Test HOST-ADMIN sign-in and UAC elevation before removing administrator membership from your OOBE account. Use WORK for everyday VM work.'

#requires -Version 5.1
#requires -RunAsAdministrator
[CmdletBinding()]
param(
    [ValidateSet('Base','Deployment','FullStack')][string]$Stage = 'Base',
    [switch]$ScanWindowsUpdate,
    [string]$VmrunPath,
    [string]$ReportPath = (Join-Path $env:ProgramData 'HostBase\Host-Validation.json')
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$checks = [System.Collections.Generic.List[object]]::new()
function Add-Check([string]$Name, [string]$Status, [string]$Detail) {
    $checks.Add([pscustomobject]@{ Name = $Name; Status = $Status; Detail = $Detail })
}
function Check([string]$Name, [scriptblock]$Test) {
    try {
        $result = & $Test
        if ($result -eq $true) { Add-Check $Name PASS 'Expected state observed.' }
        else { Add-Check $Name FAIL 'Expected state not observed.' }
    } catch { Add-Check $Name FAIL $_.Exception.Message }
}
if (-not [Environment]::Is64BitProcess) { throw 'Use 64-bit Windows PowerShell.' }
$profile = Get-Content -LiteralPath (Join-Path $PSScriptRoot 'HostProfile.json') -Raw | ConvertFrom-Json
Check 'Edition.Windows11Workstations' { ((Get-WindowsEdition -Online).Edition -eq 'ProfessionalWorkstation') -and ([int](Get-CimInstance Win32_OperatingSystem).BuildNumber -ge 22000) }
Check 'Firmware.TPM2Ready' {
    $tpm = Get-Tpm
    $version = (Get-CimInstance -Namespace root/CIMV2/Security/MicrosoftTpm -ClassName Win32_Tpm).SpecVersion
    $tpm.TpmPresent -and $tpm.TpmReady -and ($version -match '(^|,\s*)2\.0')
}
Check 'Firmware.SecureBoot' { Confirm-SecureBootUEFI }
Check 'Hypervisor.WHP' { (Get-WindowsOptionalFeature -Online -FeatureName HypervisorPlatform).State -eq 'Enabled' }
Check 'Hypervisor.Running' { (Get-CimInstance Win32_ComputerSystem).HypervisorPresent }
Check 'Security.VBSRunning' { (Get-CimInstance -Namespace root/Microsoft/Windows/DeviceGuard -ClassName Win32_DeviceGuard).VirtualizationBasedSecurityStatus -eq 2 }
Check 'Security.HVCIRunning' { 2 -in (Get-CimInstance -Namespace root/Microsoft/Windows/DeviceGuard -ClassName Win32_DeviceGuard).SecurityServicesRunning }
Check 'Security.CredentialGuardRunning' { 1 -in (Get-CimInstance -Namespace root/Microsoft/Windows/DeviceGuard -ClassName Win32_DeviceGuard).SecurityServicesRunning }
Check 'Security.DMACapabilityAvailable' { 3 -in (Get-CimInstance -Namespace root/Microsoft/Windows/DeviceGuard -ClassName Win32_DeviceGuard).AvailableSecurityProperties }
Add-Check 'Firmware.KernelDMAProtection' MANUAL 'Confirm Kernel DMA Protection = On in msinfo32; an available DMA capability is not proof every peripheral is isolated. Confirm firmware IOMMU, SMM/WSMT and MOR support.'
Check 'Recovery.WinRE' {
    $output = & reagentc.exe /info
    if ($LASTEXITCODE -ne 0) { throw 'reagentc /info failed.' }
    # This answer file installs en-US. Validate English output; other locales need a localized check.
    ($output -join "`n") -match 'Windows RE status:\s+Enabled'
}
foreach ($name in $profile.requiredServices) {
    $serviceName = $name
    Check "Service.$name.PresentNotDisabled" {
        $service = Get-Service -Name $serviceName
        $service.StartType -ne 'Disabled'
    }
}
Check 'Service.DiagTrackRunning' { (Get-Service DiagTrack).Status -eq 'Running' }
Check 'Service.BFERunning' { (Get-Service BFE).Status -eq 'Running' }
Check 'Service.SecurityCenterRunning' { (Get-Service wscsvc).Status -eq 'Running' }
Check 'EDR.SensorAvailable' { [bool](Get-Service Sense -ErrorAction SilentlyContinue) }
Add-Check 'Services.TriggerStart' INFO 'VaultSvc, Windows Installer, update services and Sense before onboarding may be stopped normally. They must be present and usable; all-services-running is not a valid baseline.'
Check 'Servicing.ComponentStoreHealth' { (Repair-WindowsImage -Online -CheckHealth).ImageHealthState -eq 'Healthy' }
Check 'Network.IPv4Retained' {
    @((Get-NetAdapterBinding -ComponentID ms_tcpip) | Where-Object Enabled -EQ $true).Count -gt 0
}
Check 'Network.PhysicalProfilesPublic' {
    $found = $false
    foreach ($adapter in @(Get-NetAdapter -Physical)) {
        foreach ($connection in @(Get-NetConnectionProfile -InterfaceIndex $adapter.ifIndex -ErrorAction SilentlyContinue)) {
            $found = $true
            if ($connection.NetworkCategory -ne 'Public') { return $false }
        }
    }
    $found
}
Check 'Security.NoAutomaticLogon' {
    $key = Get-Item -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'
    $key.GetValue('AutoAdminLogon','0') -ne '1'
}
Check 'Security.UAC' {
    $uac = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System'
    $uac.EnableLUA -eq 1 -and $uac.PromptOnSecureDesktop -eq 1
}
Check 'Security.RemoteDesktopDenied' { (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server').fDenyTSConnections -eq 1 }
Check 'Security.SMB1Disabled' { -not (Get-SmbServerConfiguration).EnableSMB1Protocol }
Check 'Security.TrimCompleted' {
    $result = Get-Content -LiteralPath (Join-Path $env:ProgramData 'HostBase\Trim-Apps.json') -Raw | ConvertFrom-Json
    $result.FailureCount -eq 0
}
if ($Stage -ne 'FullStack') {
    Check 'Security.NativeFirewallBaseline' {
        $bad = @(Get-NetFirewallProfile | Where-Object { $_.Enabled -ne 'True' -or $_.DefaultInboundAction -ne 'Block' })
        $bad.Count -eq 0
    }
    Check 'Security.DefenderActive' {
        $av = Get-MpComputerStatus
        $av.AMRunningMode -eq 'Normal' -and $av.AntivirusEnabled -and $av.RealTimeProtectionEnabled
    }
}
if ($ScanWindowsUpdate) {
    try {
        $session = New-Object -ComObject Microsoft.Update.Session
        $searcher = $session.CreateUpdateSearcher()
        $result = $searcher.Search("IsInstalled=0 and IsHidden=0 and Type='Software'")
        if ($result.ResultCode -ne 2) { throw "Windows Update scan result code $($result.ResultCode); not a complete success." }
        if ($result.Updates.Count -eq 0) { Add-Check 'Servicing.UpdateScan' PASS 'A current software-update scan completed; no pending software updates.' }
        else { Add-Check 'Servicing.UpdateScan' FAIL "$($result.Updates.Count) software updates pending. Install/reboot and scan again." }
    } catch { Add-Check 'Servicing.UpdateScan' FAIL $_.Exception.Message }
} else { Add-Check 'Servicing.UpdateScan' MANUAL 'Run again with -ScanWindowsUpdate after installing updates and rebooting. Updates have not been tested by this run.' }
if ($Stage -ne 'Base') {
    Check 'Encryption.BitLockerProtected' {
        $volume = Get-BitLockerVolume -MountPoint $env:SystemDrive
        $volume.ProtectionStatus -eq 'On' -and $volume.VolumeStatus -eq 'FullyEncrypted'
    }
    Add-Check 'Encryption.RecoveryKeyEscrow' MANUAL 'Confirm the current recovery key is backed up off this laptop, accessible independently, and matches the protector ID. The script never reads or prints the recovery password.'
    Check 'Accounts.WORKIsStandard' {
        $user = Get-LocalUser WORK
        $admins = @(Get-LocalGroupMember -SID 'S-1-5-32-544')
        @($admins | Where-Object { $_.SID -eq $user.SID }).Count -eq 0 -and $user.Enabled
    }
    Check 'Accounts.HostAdminExists' {
        $user = Get-LocalUser HOST-ADMIN
        @((Get-LocalGroupMember -SID 'S-1-5-32-544') | Where-Object { $_.SID -eq $user.SID }).Count -eq 1 -and $user.Enabled
    }
    Add-Check 'Accounts.CredentialsVerified' MANUAL 'Test HOST-ADMIN sign-in/UAC and WORK sign-in; verify unique passwords/Hello, then demote or disable the original OOBE admin. Account presence alone does not prove password strength.'
} else { Add-Check 'Encryption.BitLocker' INFO 'Base stage preserves encryption capability. Encryption and recovery-key escrow are mandatory before hostile-network deployment.' }
if ($Stage -eq 'FullStack') {
    Check 'EDR.SenseRunning' { (Get-Service Sense).Status -eq 'Running' }
    Check 'EDR.OnboardedLocally' {
        (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows Advanced Threat Protection\Status').OnboardingState -eq 1
    }
    Check 'AV.BitdefenderRegistered' {
        @((Get-CimInstance -Namespace root/SecurityCenter2 -ClassName AntivirusProduct) | Where-Object displayName -Match '(?i)Bitdefender').Count -gt 0
    }
    Check 'AV.DefenderPassiveOrEDRBlockMode' { (Get-MpComputerStatus).AMRunningMode -match '^(Passive|EDR Block Mode)' }
    foreach ($vmnet in @('VMnet1','VMnet8')) {
        $vmnetName = $vmnet
        Check "VMware.Adapter.$vmnet" { @((Get-NetAdapter -IncludeHidden) | Where-Object Name -Match "\b$vmnetName\b").Count -gt 0 }
    }
    foreach ($executable in @('vmnat.exe','vmnetdhcp.exe')) {
        $image = [regex]::Escape($executable)
        Check "VMware.Service.$executable" {
            @((Get-CimInstance Win32_Service) | Where-Object { $_.PathName -match "(?i)\b$image\b" -and $_.State -eq 'Running' }).Count -gt 0
        }
    }
    Check 'VMware.VmrunList' {
        $path = $VmrunPath
        if (-not $path) {
            $command = Get-Command vmrun.exe -ErrorAction SilentlyContinue
            if (-not $command) { throw 'Supply -VmrunPath for the installed signed VMware vmrun.exe.' }
            $path = $command.Source
        }
        if (-not (Test-Path -LiteralPath $path)) { throw 'vmrun.exe not found.' }
        $output = & $path -T ws list
        if ($LASTEXITCODE -ne 0) { throw "vmrun list failed: exit $LASTEXITCODE." }
        ($output -join "`n") -match 'Total running VMs:\s*\d+'
    }
    Add-Check 'EDR.CloudHealth' MANUAL 'Verify a recent device check-in in Defender portal; review SENSE errors and license entitlement. Local onboarding state alone cannot prove reporting.'
    Add-Check 'VPN.FirewallAndLeakTests' MANUAL 'Verify Mullvad lockdown, boot/disconnect behavior, IPv4/IPv6/DNS leak tests and Bitdefender health/firewall with VM NAT traffic. Test exceptions and recovery on a trusted staging network.'
    Add-Check 'VMware.GuestSmoke' MANUAL 'Boot a representative VM with VBS/HVCI still running. Verify guest DHCP/NAT/DNS, intended isolation, encrypted VM credentials and restart. vmrun list alone does not prove launch/networking.'
    Add-Check 'Tooling.BuildSmoke' MANUAL 'If host-side image automation is used, test Python/pywin32/keyring and a real Packer build over a temporary host-reachable VMnet. Remove build access before sandbox deployment.'
}
$failed = @($checks.ToArray() | Where-Object Status -EQ FAIL).Count
$manual = @($checks.ToArray() | Where-Object Status -EQ MANUAL).Count
$report = [ordered]@{
    Stage = $Stage; GeneratedUtc = [DateTime]::UtcNow.ToString('o'); Failed = $failed
    ManualChecksOutstanding = $manual; DeploymentReady = $false
    Note = 'Read-only checks and manual prerequisites. Never interpret exit 0 as approval to deploy.'
    Checks = @($checks.ToArray())
}
$report | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $ReportPath -Encoding UTF8
$checks.ToArray() | Format-Table Name,Status,Detail -Wrap
Write-Host "Failures: $failed; manual checks outstanding: $manual. Report: $ReportPath"
if ($failed) { exit 1 }
if ($manual) { exit 2 }
exit 0

#requires -Version 5.1
#requires -RunAsAdministrator
[CmdletBinding()]
param()
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$profile = Get-Content -LiteralPath (Join-Path $PSScriptRoot 'HostProfile.json') -Raw | ConvertFrom-Json
$failures = [System.Collections.Generic.List[string]]::new()
$results = [System.Collections.Generic.List[object]]::new()
if (@($profile.removeAppx | Where-Object { $_ -in $profile.protectedAppx }).Count) { throw 'Protected Appx in removal list.' }
$provisioned = @(Get-AppxProvisionedPackage -Online)
$registered = @(Get-AppxPackage -AllUsers)
foreach ($name in $profile.removeAppx) {
    foreach ($package in @($provisioned | Where-Object DisplayName -EQ $name)) {
        try {
            Remove-AppxProvisionedPackage -Online -AllUsers -PackageName $package.PackageName | Out-Null
            $results.Add([ordered]@{ Kind = 'ProvisionedAppx'; Name = $name; Status = 'Removed' })
        } catch { $failures.Add("Provisioned $name : $($_.Exception.Message)") }
    }
    foreach ($package in @($registered | Where-Object Name -EQ $name)) {
        if ($package.IsFramework -or $package.NonRemovable) {
            $failures.Add("Protected/nonremovable package retained: $name"); continue
        }
        try {
            Remove-AppxPackage -Package $package.PackageFullName -AllUsers
            $results.Add([ordered]@{ Kind = 'RegisteredAppx'; Name = $name; Status = 'Removed' })
        } catch { $failures.Add("Registered $name : $($_.Exception.Message)") }
    }
}
foreach ($capability in @(Get-WindowsCapability -Online)) {
    $prefix = ($capability.Name -split '~')[0]
    if ($prefix -in $profile.removeCapabilityPrefixes -and $capability.State -eq 'Installed') {
        try {
            Remove-WindowsCapability -Online -Name $capability.Name | Out-Null
            $results.Add([ordered]@{ Kind = 'Capability'; Name = $capability.Name; Status = 'Removed' })
        } catch { $failures.Add("Capability $prefix : $($_.Exception.Message)") }
    }
}
# Uninstall via the Windows-supplied binary; do not delete installers or service files.
$oneDrivePaths = @("$env:SystemRoot\System32\OneDriveSetup.exe", "$env:SystemRoot\SysWOW64\OneDriveSetup.exe")
$oneDrive = $oneDrivePaths | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
if ($oneDrive) {
    try {
        $p = Start-Process -FilePath $oneDrive -ArgumentList '/uninstall' -Wait -PassThru
        if ($p.ExitCode -ne 0) { throw "OneDrive uninstaller exit code $($p.ExitCode)." }
        $results.Add([ordered]@{ Kind = 'DesktopApp'; Name = 'OneDrive'; Status = 'UninstallRequested' })
    } catch { $failures.Add($_.Exception.Message) }
}
$root = Join-Path $env:ProgramData 'HostBase'
if (-not (Test-Path -LiteralPath $root)) {
    throw 'Run Apply-Base.ps1 first so the report directory has protected ACLs.'
}
[ordered]@{ Results = @($results.ToArray()); Failures = @($failures.ToArray()); FailureCount = $failures.Count } |
    ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $root 'Trim-Apps.json') -Encoding UTF8
foreach ($failure in $failures) { Write-Warning $failure }
